//! Explicit numerical access to existing shading math, not a new light preset/renderer.
use super::kit::*;
fn unit(v:[f64;3])->Result<[f64;3],String>{if v.iter().any(|x|!x.is_finite()){return Err("finite direction required".into());}let scale=v.iter().fold(0.0f64,|a,b|a.max(b.abs()));if scale==0.0{return Err("nonzero direction required".into());}let q=v.map(|x|x/scale);let m=q.iter().map(|x|x*x).sum::<f64>().sqrt();Ok(q.map(|x|x/m))}
fn vector(a:&Value,k:&str)->Result<[f64;3],String>{serde_json::from_value(a.get(k).ok_or_else(||format!("{k} required"))?.clone()).map_err(|e|e.to_string())}
pub fn commands()->Vec<Command>{vec![
Command{name:"lighting_brdf_sample",mutates:false,description:"Evaluate existing raw material BRDF with explicit normal, light and view unit directions and albedo. Returns diffuse/specular terms including N dot L. No rig/preset, no project mutation, not a new physically calibrated renderer.",schema:obj(vec![("normal",json!({"type":"array","minItems":3,"maxItems":3})),("light",json!({"type":"array","minItems":3,"maxItems":3})),("view",json!({"type":"array","minItems":3,"maxItems":3})),("albedo",json!({"type":"array","minItems":3,"maxItems":3})),("material",json!({"type":"object"}))],&["normal","light","view","albedo","material"]),run:|_,a|{
 let(n,l,v)=(unit(vector(a,"normal")?)?,unit(vector(a,"light")?)?,unit(vector(a,"view")?)?);let albedo=vector(a,"albedo")?;if albedo.iter().any(|x|!x.is_finite()||*x<0.0||*x>4.0){return Err("albedo finite 0..4 required".into());}
 let m:crate::lighting::Material=serde_json::from_value(a.get("material").ok_or("material required")?.clone()).map_err(|e|e.to_string())?;crate::lighting::validate_material(&m)?;let(d,s)=crate::lighting::brdf(n,l,v,&m,albedo);if d.iter().chain(&s).any(|x|!x.is_finite()){return Err("BRDF result nonfinite".into());}Ok(json!({"diffuse":d,"specular":s,"convention":"existing Kimo BRDF times NdotL; not radiometric calibration; diffuse already includes albedo"}))}},
Command{name:"lighting_incident_sample",mutates:false,description:"Evaluate an explicit point/directional/spot light at a surface position with existing attenuation/cone math. Returns direction, attenuation and incident RGB; does not set lights or alter rendering.",schema:obj(vec![("definition",json!({"type":"object"})),("position",json!({"type":"array","minItems":3,"maxItems":3}))],&["definition","position"]),run:|_,a|{
 let light:crate::lighting::LightDef=serde_json::from_value(a.get("definition").ok_or("definition required")?.clone()).map_err(|e|e.to_string())?;crate::lighting::validate_light(&light)?;let p=vector(a,"position")?;if p.iter().any(|x|!x.is_finite()||x.abs()>1e9){return Err("position finite within +/-1e9 required".into());}let(d,k)=crate::lighting::light_at(&light,p);let rgb=light.color.map(|c|if light.enabled{c*light.intensity*k}else{0.0});if d.iter().chain(&rgb).any(|x|!x.is_finite()){return Err("incident result overflow".into());}Ok(json!({"direction":d,"attenuation":k,"incident_rgb":rgb,"units":"existing Kimo frame-normalized artistic light units, not photometric"}))}}
]}
